fn deserialize_optional_generic_json<'de, D>(deserializer: D) -> Result<Option<serde_json::Value>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    superscalar::scalars::json_scalar::serde::deserialize(deserializer).map(Some)
}
